// To understand auto deduction, map it to template deduction.

// Case 1: auto x = 27;
// Conceptually, this is like:
template<typename T> void f(T param); // ParamType is T (value)
f(27); // T is deduced as int, param is int. So, x is int.

int i = 42;

// Case 2: const auto cx = i;
// Conceptually, this is like:
template<typename T> void g(const T param); // ParamType is const T
g(i); // T is deduced as int, param is const int. So, cx is const int.

// Case 3: const auto& rx = i;
// Conceptually, this is like:
template<typename T> void h(const T& param); // ParamType is const T&
h(i); // T is deduced as int, param is const int&. So, rx is const int&.
